package it.xarber.tvhome;

import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.graphics.*;
import android.hardware.display.VirtualDisplay;
import android.media.*;
import android.media.projection.*;
import android.os.*;
import android.util.Base64;
import org.json.*;
import java.io.ByteArrayOutputStream;
import java.util.ArrayDeque;

/** Consent-only, bounded in-memory app capture. No HDMI/secure-surface bypass or recording files. */
public final class AppPreviewService extends Service {
    private static final Object lock=new Object();
    private static String owner="",phase="idle",requestId="";private static volatile long requestedAt,lastPoll,startedAt;private static long imageSequence,audioSequence;
    private static byte[] jpeg;private static final ArrayDeque<Audio> audio=new ArrayDeque<>();private static boolean sound;
    private static volatile AppPreviewService live;
    private static final class Audio {long sequence;byte[] bytes;Audio(long sequence,byte[] bytes){this.sequence=sequence;this.bytes=bytes;}}
    private final Handler main=new Handler(Looper.getMainLooper());private HandlerThread worker;private ImageReader reader;private VirtualDisplay display;private MediaProjection projection;private AudioRecord recorder;private Thread audioWorker;private volatile boolean running;
    public static JSONObject request(Context context,String identity)throws Exception{synchronized(lock){long now=SystemClock.elapsedRealtime();if(awaiting()){if(owner.equals(identity))return state(identity,-1,-1);return SystemRemoteController.error("preview_busy");}if(!owner.isEmpty()&&!owner.equals(identity)&&now-lastPoll<8000)return SystemRemoteController.error("preview_busy");if(live!=null)return SystemRemoteController.error("preview_busy");owner=identity;phase="awaiting_tv";requestId=java.util.UUID.randomUUID().toString();requestedAt=lastPoll=now;jpeg=null;audio.clear();sound=false;imageSequence=audioSequence=0;}HomeForeground.request(context,false);return state(identity,-1,-1);}
    public static String approvalId(){synchronized(lock){return awaiting()?requestId:"";}}
    public static boolean awaiting(){synchronized(lock){if(phase.equals("awaiting_tv")&&SystemClock.elapsedRealtime()-requestedAt>60000){phase="approval_expired";owner="";}return phase.equals("awaiting_tv");}}
    public static void denied(String approval){synchronized(lock){if(!requestId.equals(approval))return;phase="denied";owner="";}}
    public static void approved(Context context,String approval,int result,Intent data){if(!awaiting()||!approvalId().equals(approval))return;Intent intent=new Intent(context,AppPreviewService.class).putExtra("result",result).putExtra("consent",data).putExtra("approval",approval);try{context.startForegroundService(intent);}catch(RuntimeException failure){synchronized(lock){phase="capture_unavailable";owner="";}}}
    public static JSONObject state(String identity,long imageAfter,long audioAfter)throws Exception{synchronized(lock){awaiting();if(!owner.isEmpty()&&!owner.equals(identity))return SystemRemoteController.error("preview_owner_required");lastPoll=SystemClock.elapsedRealtime();JSONObject value=new JSONObject().put("status",phase).put("audioAvailable",sound).put("imageSequence",imageSequence).put("audioSequence",audioSequence).put("sampleRate",16000);if(phase.equals("sharing")&&jpeg!=null&&imageSequence>imageAfter)value.put("image","data:image/jpeg;base64,"+Base64.encodeToString(jpeg,Base64.NO_WRAP));JSONArray chunks=new JSONArray();for(Audio item:audio)if(phase.equals("sharing")&&item.sequence>audioAfter)chunks.put(new JSONObject().put("sequence",item.sequence).put("pcm",Base64.encodeToString(item.bytes,Base64.NO_WRAP)));return value.put("audio",chunks);}}
    public static void cancelAll(Context context){synchronized(lock){phase="stopped";owner="";requestId="";jpeg=null;audio.clear();}context.stopService(new Intent(context,AppPreviewService.class));}
    public static JSONObject end(Context context,String identity){synchronized(lock){if(!owner.isEmpty()&&!owner.equals(identity))return SystemRemoteController.error("preview_owner_required");phase="stopped";owner="";jpeg=null;audio.clear();}context.stopService(new Intent(context,AppPreviewService.class));try{return new JSONObject().put("accepted",true);}catch(Exception ignored){return new JSONObject();}}
    @Override public android.os.IBinder onBind(Intent intent){return null;}
    @Override public int onStartCommand(Intent intent,int flags,int id){if(intent==null||"stop".equals(intent.getAction())||!awaiting()||!approvalId().equals(intent.getStringExtra("approval"))){stopSelf();return START_NOT_STICKY;}live=this;
        NotificationManager notifications=getSystemService(NotificationManager.class);notifications.createNotificationChannel(new NotificationChannel("app_preview","App preview",NotificationManager.IMPORTANCE_LOW));PendingIntent stop=PendingIntent.getService(this,0,new Intent(this,AppPreviewService.class).setAction("stop"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notice=new Notification.Builder(this,"app_preview").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle("Aurea app preview").setContentText("Screen sharing is active. HDMI and protected content are excluded.").setOngoing(true).addAction(new Notification.Action.Builder(null,"Stop sharing",stop).build()).build();
        try{if(Build.VERSION.SDK_INT>=29)startForeground(1702,notice,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);else startForeground(1702,notice);
        Intent consent=intent.getParcelableExtra("consent");projection=getSystemService(MediaProjectionManager.class).getMediaProjection(intent.getIntExtra("result",0),consent);if(projection==null)throw new IllegalStateException();worker=new HandlerThread("AureaPreview");worker.start();Handler handler=new Handler(worker.getLooper());projection.registerCallback(new MediaProjection.Callback(){@Override public void onStop(){stopSelf();}},main);
            android.util.DisplayMetrics metrics=getResources().getDisplayMetrics();int width=480,height=Math.max(120,Math.min(480,Math.round(width*metrics.heightPixels/(float)metrics.widthPixels)));reader=ImageReader.newInstance(width,height,PixelFormat.RGBA_8888,2);final long[] last={0};reader.setOnImageAvailableListener(source->{try(Image image=source.acquireLatestImage()){if(image==null||SystemClock.elapsedRealtime()-last[0]<250)return;last[0]=SystemClock.elapsedRealtime();Image.Plane plane=image.getPlanes()[0];int padded=width+(plane.getRowStride()-plane.getPixelStride()*width)/plane.getPixelStride();Bitmap raw=Bitmap.createBitmap(padded,height,Bitmap.Config.ARGB_8888);raw.copyPixelsFromBuffer(plane.getBuffer());Bitmap crop=Bitmap.createBitmap(raw,0,0,width,height);ByteArrayOutputStream bytes=new ByteArrayOutputStream();crop.compress(Bitmap.CompressFormat.JPEG,45,bytes);if(crop!=raw)crop.recycle();raw.recycle();if(bytes.size()<=80000)synchronized(lock){if(running&&phase.equals("sharing")&&!owner.isEmpty()){jpeg=bytes.toByteArray();imageSequence++;}}}catch(Exception ignored){}},handler);
            display=projection.createVirtualDisplay("Aurea app preview",width,height,metrics.densityDpi,android.hardware.display.DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,handler);running=true;startedAt=lastPoll=SystemClock.elapsedRealtime();synchronized(lock){phase="sharing";}if(Build.VERSION.SDK_INT>=29&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED)startSound();main.post(watchdog);
        }catch(Exception failure){synchronized(lock){phase="capture_unavailable";}stopSelf();}return START_NOT_STICKY;}
    @android.annotation.TargetApi(29) @android.annotation.SuppressLint("MissingPermission") private void startSound(){try{AudioPlaybackCaptureConfiguration config=new AudioPlaybackCaptureConfiguration.Builder(projection).addMatchingUsage(AudioAttributes.USAGE_MEDIA).addMatchingUsage(AudioAttributes.USAGE_GAME).build();int size=Math.max(8192,AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT));recorder=new AudioRecord.Builder().setAudioFormat(new AudioFormat.Builder().setSampleRate(16000).setChannelMask(AudioFormat.CHANNEL_IN_MONO).setEncoding(AudioFormat.ENCODING_PCM_16BIT).build()).setAudioPlaybackCaptureConfig(config).setBufferSizeInBytes(size).build();recorder.startRecording();synchronized(lock){sound=true;}final AudioRecord input=recorder;audioWorker=new Thread(()->{byte[] buffer=new byte[4096];try{while(running){int count=input.read(buffer,0,buffer.length);if(count<=0)break;synchronized(lock){if(!phase.equals("sharing")||owner.isEmpty())break;audio.addLast(new Audio(++audioSequence,java.util.Arrays.copyOf(buffer,count)));while(audio.size()>6)audio.removeFirst();}}}catch(IllegalStateException ignored){}finally{input.release();java.util.Arrays.fill(buffer,(byte)0);synchronized(lock){if(live==AppPreviewService.this)sound=false;}}},"AureaPreviewAudio");audioWorker.start();}catch(Exception unavailable){synchronized(lock){sound=false;}}}
    private final Runnable watchdog=new Runnable(){@Override public void run(){long now=SystemClock.elapsedRealtime();if(!PreviewAccess.alive(now,startedAt,lastPoll)){stopSelf();return;}main.postDelayed(this,1000);}};
    @Override public void onDestroy(){running=false;main.removeCallbacksAndMessages(null);if(recorder!=null){try{recorder.stop();}catch(Exception ignored){}if(audioWorker==null)recorder.release();else try{audioWorker.join(300);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}recorder=null;}if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null){MediaProjection current=projection;projection=null;current.stop();}if(worker!=null)worker.quitSafely();synchronized(lock){if(phase.equals("sharing")||phase.equals("awaiting_tv"))phase="stopped";jpeg=null;audio.clear();sound=false;owner="";}live=null;super.onDestroy();}
}
